(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-636":{scenario:{company:"Mộc Lan Architects & Interiors",supervisor:{name:"Quách Thùy Trang",role:{vi:"Giám đốc thiết kế",en:"Design Director"}},ref_code:"ARC-4410",title:{vi:"Ý tưởng đẹp phải đúng quy chuẩn.",en:"Great concepts must meet the codes."},brief:{vi:"Bạn hoàn thiện bảng chỉ tiêu phương án ARC-4410 cho tòa hỗn hợp trên lô đất 4 000 m2, quy hoạch cho phép hệ số sử dụng đất tối đa 5,50 (mô phỏng). Sàn trên mặt đất 22 400 m2, trong đó tầng kỹ thuật và gian lánh nạn 800 m2. Hai tầng hầm 7 200 m2 gồm 6 400 m2 đỗ xe, kỹ thuật và 800 m2 siêu thị. Nhiệm vụ thiết kế vừa điều chỉnh khối tháp thành căn hộ chung cư để bán. Hãy sửa nhóm nguy hiểm cháy theo công năng và hệ số sử dụng đất, rồi lập báo cáo có căn cứ.",en:"You are finalizing scheme indicator sheet ARC-4410 for a mixed-use tower on a 4,000 m2 lot; planning allows a maximum floor area ratio of 5.50 (simulated). Above-ground floor area is 22,400 m2, including 800 m2 of plant and refuge floors. Two basements total 7,200 m2: 6,400 m2 of parking and plant and 800 m2 of supermarket. The brief now makes the tower apartments for sale. Correct the fire hazard class by use and the floor area ratio, then write an evidence-based report."},reference_title:{vi:"Nhiệm vụ thiết kế điều chỉnh & bảng diện tích đã duyệt",en:"Revised design brief & approved area schedule"},fields:[{id:"FIRE_CLASS",label:{vi:"Nhóm nguy hiểm cháy theo công năng khối tháp",en:"Functional fire hazard class of the tower"},initial:"F1.2",expected:"F1.3",choices:["F1.2","F1.3","F4.3"],reference:"Nhiệm vụ thiết kế điều chỉnh",ref_value:{vi:"Khối tháp chuyển từ căn hộ dịch vụ lưu trú ngắn ngày sang căn hộ chung cư để bán",en:"Tower changed from short-stay serviced apartments to apartments for sale"},hint:{vi:"F1.2 dành cho khách sạn, ký túc xá, nơi lưu trú; nhà chung cư thuộc một nhóm khác trong hạng F1.",en:"F1.2 covers hotels, dormitories and short stays; apartment buildings are another subclass of F1."}},{id:"FAR",label:{vi:"Hệ số sử dụng đất",en:"Floor area ratio (FAR)"},initial:"5.40",expected:"5.60",reference:"Bảng tổng hợp diện tích sàn",ref_value:{vi:"Lô 4 000 m2; sàn nổi 22 400 (kỹ thuật, lánh nạn 800); hầm 7 200 (đỗ xe, kỹ thuật 6 400; siêu thị 800)",en:"Lot 4,000 m2; above ground 22,400 (plant, refuge 800); basements 7,200 (parking, plant 6,400; supermarket 800)"},hint:{vi:"Bản nháp loại toàn bộ tầng hầm; phần hầm kinh doanh vẫn phải tính vào tổng diện tích sàn.",en:"The draft excluded the whole basement; commercial basement space still counts toward floor area."}}],sop32:{vi:"Hệ số sử dụng đất = tổng diện tích sàn / diện tích lô đất. Tổng diện tích sàn tính cả tầng hầm, trừ diện tích đỗ xe, kỹ thuật, PCCC và gian lánh nạn; làm tròn 2 chữ số thập phân.",en:"FAR = gross floor area / lot area. Gross floor area includes basements but excludes parking, plant, fire safety and refuge areas; round to 2 decimals."},context:{label:"CHỈ TIÊU / ARC-4410",metrics:[{label:{vi:"Diện tích lô đất",en:"Lot area"},value:"4,000 m2"},{label:{vi:"Hệ số tối đa (mô phỏng)",en:"Max FAR (simulated)"},value:"5.50"},{label:{vi:"Sàn hầm kinh doanh",en:"Commercial basement"},value:"800 m2"}]},crisis:{vi:"Chủ đầu tư gọi: “Ghi siêu thị tầng hầm là kho kỹ thuật trên bản vẽ để hệ số dưới 5,5 cho qua thẩm định, sau này đổi công năng. Đừng cắt căn hộ nào.”",en:"The developer calls: “Label the basement supermarket as plant storage on the drawings so the FAR stays under 5.5 for approval; we change the use later. Do not cut any apartments.”"},options:{safe:{vi:"Không ghi sai công năng; báo giám đốc thiết kế và chủ đầu tư rằng phương án vượt chỉ tiêu, đề xuất giảm diện tích sàn, chuyển phần hầm sang công năng được loại trừ hoặc xin điều chỉnh quy hoạch đúng thủ tục.",en:"Do not mislabel uses; tell the design director and developer the scheme exceeds the limit and propose cutting floor area, converting the basement to an excluded use or a lawful planning amendment."},shortcut:{vi:"Đổi tên siêu thị thành kho kỹ thuật trên bản vẽ cho qua thẩm định như chủ đầu tư muốn.",en:"Rename the supermarket as plant storage on the drawings to pass approval as the developer wants."},wait:{vi:"Gửi bảng chỉ tiêu nháp như cũ và chờ cơ quan thẩm định tự phát hiện.",en:"Submit the old draft sheet and wait for the authority to spot the issue."}},questions:{vi:["Giải thích cách bạn tính lại hệ số sử dụng đất, phần diện tích nào được trừ và vì sao khối tháp thuộc nhóm F1.3.","Đề nghị ghi sai công năng tầng hầm gây hậu quả pháp lý và an toàn cháy nào? Bạn đề xuất phương án thiết kế hợp lệ ra sao?"],en:["Explain how you recalculated the FAR, which areas are excluded and why the tower falls in class F1.3.","What legal and fire safety consequences follow from mislabelling the basement use? Which lawful design options do you propose?"]},hints:{vi:["Đặt bảng chỉ tiêu nháp cạnh nhiệm vụ thiết kế điều chỉnh và kiểm tra công năng mới của khối tháp.","Theo SOP mục 3.2, liệt kê từng loại diện tích, đánh dấu phần được trừ rồi mới chia cho diện tích lô đất.","SOP mục 4.2: hồ sơ phải thể hiện đúng công năng thật; áp lực lách quy hoạch phải báo giám đốc thiết kế."],en:["Place the draft sheet next to the revised brief and check the tower's new use.","Under SOP 3.2, list each area type, mark the excluded ones and only then divide by the lot area.","SOP 4.2: drawings must show the real use; escalate any pressure to circumvent planning to the design director."]}},learning:{summary:{vi:"Kiến trúc sư thiết kế công trình và nội thất chuyển nhu cầu của chủ đầu tư thành giải pháp không gian, hình khối, vật liệu và chi tiết, cân bằng giữa thẩm mỹ, công năng, chi phí, quy hoạch và an toàn. Họ dẫn dắt phương án từ ý tưởng đến hồ sơ kỹ thuật, phối hợp kết cấu, cơ điện và giám sát tác giả. Nghề cần tư duy sáng tạo, kỹ năng trình bày, hiểu quy chuẩn xây dựng và giữ đạo đức nghề nghiệp trước áp lực thương mại.",en:"An architectural and interior designer turns a client's needs into spatial, massing, material and detail solutions, balancing aesthetics, function, cost, planning and safety. They lead a scheme from concept to technical documents, coordinate structure and MEP and provide designer supervision. The role needs creative thinking, presentation skills, command of building codes and professional ethics under commercial pressure."},responsibilities:{vi:["Phân tích nhiệm vụ thiết kế, khu đất, quy hoạch và lập ý tưởng kiến trúc, nội thất.","Phát triển mặt bằng, mặt đứng, phối cảnh và bảng chỉ tiêu kinh tế kỹ thuật.","Kiểm tra tuân thủ quy hoạch, an toàn cháy, tiếp cận người khuyết tật và tiết kiệm năng lượng.","Lựa chọn vật liệu hoàn thiện, đồ nội thất, ánh sáng và lập chỉ dẫn kỹ thuật.","Phối hợp các bộ môn, trình duyệt hồ sơ và giám sát tác giả trong thi công."],en:["Analyse the brief, site and planning rules and develop architectural and interior concepts.","Develop plans, elevations, visualizations and the techno-economic indicator sheet.","Check compliance with planning, fire safety, accessibility and energy efficiency rules.","Select finishes, furniture and lighting and write the specifications.","Coordinate disciplines, submit for approval and provide designer supervision during construction."]},competencies:[{name:{vi:"Tư duy thiết kế & sáng tạo",en:"Design thinking & creativity"},desc:{vi:"Biến nhu cầu người dùng thành ý tưởng không gian rõ ràng, có bản sắc.",en:"Turn user needs into clear spatial ideas with a distinct identity."}},{name:{vi:"Hiểu quy chuẩn",en:"Code literacy"},desc:{vi:"Vận dụng quy chuẩn quy hoạch, an toàn cháy, tiếp cận sử dụng ngay từ giai đoạn ý tưởng.",en:"Apply planning, fire safety and accessibility codes from the concept stage."}},{name:{vi:"Kỹ năng thể hiện",en:"Visual communication"},desc:{vi:"Dựng hình, diễn họa, trình bày phương án thuyết phục bằng hình ảnh và số liệu.",en:"Model, render and present schemes persuasively with images and data."}},{name:{vi:"Vật liệu & chi tiết",en:"Materials & detailing"},desc:{vi:"Hiểu đặc tính vật liệu, cấu tạo, chi phí và khả năng thi công.",en:"Understand material properties, build-ups, cost and buildability."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Bảo vệ lợi ích cộng đồng, không lách quy hoạch hay khai sai công năng.",en:"Protect the public interest and never circumvent planning or misstate uses."}}],knowledge:{vi:["QCVN 01:2021/BXD - Quy chuẩn kỹ thuật quốc gia về quy hoạch xây dựng (mật độ, hệ số sử dụng đất).","QCVN 06:2022/BXD - An toàn cháy cho nhà và công trình, phân nhóm nguy hiểm cháy theo công năng F1 đến F5.","Luật Kiến trúc số 40/2019/QH14 và quy định về chứng chỉ hành nghề kiến trúc.","Quy chuẩn hiện hành về nhà và công trình bảo đảm người khuyết tật tiếp cận sử dụng.","Nguyên lý công thái học, ánh sáng, âm học và vật liệu trong thiết kế nội thất."],en:["QCVN 01:2021/BXD - National technical regulation on construction planning (site coverage, floor area ratio).","QCVN 06:2022/BXD - Fire safety of buildings, functional fire hazard classes F1 to F5.","Architecture Law No. 40/2019/QH14 and rules on architectural practice certificates.","Current regulation on building accessibility for people with disabilities.","Principles of ergonomics, lighting, acoustics and materials in interior design."]},tools:["Phần mềm dựng hình 3D và BIM kiến trúc","Phần mềm diễn họa thời gian thực","Phần mềm CAD 2D","Bộ mẫu vật liệu hoàn thiện","Phần mềm dàn trang trình bày"],kpis:{vi:["Tỷ lệ phương án được chủ đầu tư chấp thuận sau tối đa 2 vòng chỉnh sửa.","Số ý kiến không tuân thủ quy chuẩn từ cơ quan thẩm định (mục tiêu bằng 0).","Chênh lệch chi phí hoàn thiện thực tế so với ngân sách thiết kế.","Mức độ hài lòng của người sử dụng sau khi đưa vào khai thác."],en:["Share of schemes approved by the client within 2 revision rounds.","Code non-compliance comments from the authority (target zero).","Variance of actual fit-out cost against the design budget.","User satisfaction after occupancy."]},day:[{time:"08:30",vi:"Rà soát phản hồi của chủ đầu tư về phương án sảnh và căn hộ mẫu.",en:"Review client feedback on the lobby scheme and show apartment."},{time:"10:00",vi:"Phát triển mặt bằng tầng điển hình, kiểm tra lối thoát nạn và bảng diện tích.",en:"Develop the typical floor plan and check escape routes and the area schedule."},{time:"13:30",vi:"Làm việc với nhà cung cấp về mẫu vật liệu, ánh sáng và đồ nội thất.",en:"Meet suppliers on material samples, lighting and furniture."},{time:"15:30",vi:"Họp phối hợp kết cấu, cơ điện về cao độ trần và trục kỹ thuật.",en:"Coordinate ceiling heights and service shafts with structure and MEP."},{time:"17:00",vi:"Cập nhật bảng chỉ tiêu, phối cảnh và chuẩn bị bài trình bày.",en:"Update the indicator sheet and renders and prepare the presentation."}],mistakes:{vi:["Loại toàn bộ tầng hầm khỏi tổng diện tích sàn, kể cả phần kinh doanh.","Không cập nhật nhóm nguy hiểm cháy khi công năng công trình thay đổi.","Chọn vật liệu theo thẩm mỹ mà bỏ qua yêu cầu an toàn cháy, độ bền và bảo trì."],en:["Excluding every basement from gross floor area, including commercial space.","Not updating the fire hazard class when the building use changes.","Choosing materials for looks while ignoring fire safety, durability and maintenance."]},career:[{vi:"Họa viên, kiến trúc sư tập sự",en:"Draftsperson, graduate architect"},{vi:"Kiến trúc sư thiết kế",en:"Project architect"},{vi:"Kiến trúc sư chủ trì",en:"Lead architect"},{vi:"Giám đốc thiết kế, kiến trúc sư trưởng",en:"Design director, principal architect"}],glossary:[{term:"FAR",vi:"Hệ số sử dụng đất: tỷ lệ giữa tổng diện tích sàn tính theo quy chuẩn và diện tích lô đất.",en:"Floor area ratio: gross floor area as defined by the code divided by lot area."},{term:"Mật độ xây dựng",vi:"Tỷ lệ diện tích chiếm đất của công trình trên diện tích lô đất.",en:"Ratio of building footprint to lot area."},{term:"F1.3",vi:"Nhóm nguy hiểm cháy theo công năng dành cho nhà chung cư trong QCVN 06:2022/BXD.",en:"Functional fire hazard subclass for apartment buildings in QCVN 06:2022/BXD."},{term:"Concept design",vi:"Thiết kế ý tưởng thể hiện định hướng không gian, hình khối và các giải pháp chính.",en:"Early design stage expressing spatial direction, massing and key solutions."},{term:"Moodboard",vi:"Bảng tập hợp hình ảnh, vật liệu, màu sắc định hướng ngôn ngữ thiết kế nội thất.",en:"Board of images, materials and colours that sets the interior design language."}],quiz:[{q:{vi:"Lô đất 2 000 m2, tổng diện tích sàn tính hệ số là 9 000 m2. Hệ số sử dụng đất là bao nhiêu?",en:"A 2,000 m2 lot has 9,000 m2 of countable gross floor area. What is the FAR?"},options:{vi:["4,5","2,2","9,0","0,22"],en:["4.5","2.2","9.0","0.22"]},answer:0,explain:{vi:"Hệ số sử dụng đất = 9 000 / 2 000 = 4,5.",en:"FAR = 9,000 / 2,000 = 4.5."}},{q:{vi:"Theo QCVN 06:2022/BXD, khách sạn và ký túc xá thuộc nhóm nguy hiểm cháy theo công năng nào?",en:"Under QCVN 06:2022/BXD, which functional fire hazard class covers hotels and dormitories?"},options:{vi:["F1.3","F1.2","F3.1","F4.3"],en:["F1.3","F1.2","F3.1","F4.3"]},answer:1,explain:{vi:"F1.2 gồm khách sạn, ký túc xá, nhà nghỉ; nhà chung cư thuộc F1.3.",en:"F1.2 covers hotels, dormitories and guesthouses; apartment buildings are F1.3."}},{q:{vi:"Chủ đầu tư đề nghị ghi siêu thị tầng hầm là kho kỹ thuật để qua thẩm định. Bạn làm gì?",en:"The developer asks you to label the basement supermarket as plant storage to pass approval. What do you do?"},options:{vi:["Làm theo vì chủ đầu tư chịu trách nhiệm","Ghi mơ hồ là không gian đa năng","Từ chối, báo giám đốc thiết kế và đề xuất phương án điều chỉnh hợp lệ","Bỏ tầng hầm khỏi hồ sơ trình duyệt"],en:["Comply because the developer is responsible","Label it vaguely as flexible space","Refuse, inform the design director and propose lawful revisions","Leave the basement out of the submission"]},answer:2,explain:{vi:"Khai sai công năng là vi phạm pháp luật và làm sai lệch giải pháp an toàn cháy; kiến trúc sư phải từ chối và đề xuất phương án hợp lệ.",en:"Misstating use breaks the law and distorts fire safety design; the architect must refuse and propose lawful options."}},{q:{vi:"Thành phần nào được trừ khi tính tổng diện tích sàn cho hệ số sử dụng đất?",en:"Which area is excluded from gross floor area when computing FAR?"},options:{vi:["Sàn siêu thị tầng hầm","Sàn căn hộ","Sàn văn phòng","Sàn đỗ xe của công trình"],en:["Basement supermarket floor","Apartment floors","Office floors","The building's parking floors"]},answer:3,explain:{vi:"Diện tích đỗ xe, kỹ thuật, PCCC và gian lánh nạn được trừ; diện tích kinh doanh dưới hầm vẫn được tính.",en:"Parking, plant, fire safety and refuge areas are excluded; commercial basement space still counts."}}],tools_en:["3D modeling and architectural BIM software","Real-time rendering software","2D CAD software","Finish material sample kit","Presentation layout software"]}}})})(window.KKR);
